local ffi = require("ffi")
ffi.cdef[[
    typedef struct {
        int a;
        double b;
        char c[10];
        struct { int x; int y; } nested;
    } complex_t;

    typedef union {
        int i;
        float f;
        char bytes[4];
    } union_t;

    typedef enum {
        VAL_A = 1,
        VAL_B = 2,
        VAL_C = 4
    } enum_t;
]]

for i = 1, 50 do
    local c = ffi.new("complex_t")
    c.a = i
    c.b = i * 1.5
    c.nested.x = i * 2
    c.nested.y = i * 3

    local u = ffi.new("union_t")
    u.i = i
    local _ = u.f
end
print("complex ffi done")

