local ffi = require("ffi")
ffi.cdef[[
    typedef struct { int x; int y; } point_t;
]]

local point_mt = {
    __add = function(a, b)
        return ffi.new("point_t", a.x + b.x, a.y + b.y)
    end,
    __tostring = function(p)
        return string.format("(%d,%d)", p.x, p.y)
    end
}

ffi.metatype("point_t", point_mt)

